#!/usr/bin/env python3
from pathlib import Path
from datetime import datetime
import base64
import gzip
import hashlib
import shutil
import subprocess
import sys

FILES = {'app/(tabs)/shop.tsx': '', 'app/context/PurchasesContext.tsx': ''}
EXPECTED_ORIGINAL_SHA256 = {'app/(tabs)/shop.tsx': 'a885c9993283bcefd5204f0cfe4e1ffd0ce6ac2bdbfae8738ec6f5559168048b', 'app/context/PurchasesContext.tsx': 'fe32608c57e86535b1d4da7c43f4ec83ae99bf711ece7736049a0ead902be557'}
EXPECTED_PATCHED_SHA256 = {'app/(tabs)/shop.tsx': '6d796674bcbbc12726b8078e7d073c8ec2076a095cd60ee48082ca325951e70a', 'app/context/PurchasesContext.tsx': '385967eb20e7b47e244ed9c723dbe6199df9a23bb7aff2a57bf372a27206ecbc'}


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def decode(value: str) -> bytes:
    return gzip.decompress(base64.b64decode(value.encode("ascii")))


def main() -> int:
    root = Path.cwd()
    print("🔧 Nova Tutoring IAP persistence + restore fix")

    missing = [relative for relative in FILES if not (root / relative).is_file()]
    if missing:
        print("❌ Run this from the Nova_Tutoring_expo_3 project folder.")
        for relative in missing:
            print("   Missing:", relative)
        return 1

    already_patched = all(
        sha256(root / relative) == EXPECTED_PATCHED_SHA256[relative]
        for relative in FILES
    )
    if already_patched:
        print("✅ The IAP fix is already installed.")
        return 0

    mismatches = []
    for relative in FILES:
        current = sha256(root / relative)
        if current != EXPECTED_ORIGINAL_SHA256[relative]:
            mismatches.append((relative, current))

    if mismatches:
        print("❌ I stopped before writing anything because these files changed")
        print("   after the debug ZIP was created:")
        for relative, current in mismatches:
            print(f"   {relative}")
            print(f"      current SHA: {current}")
            print(f"      expected:    {EXPECTED_ORIGINAL_SHA256[relative]}")
        print("\nUpload fresh copies of those files before applying this installer.")
        return 2

    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    backup_root = root / "backups" / f"before_iap_restore_fix_{stamp}"

    for relative in FILES:
        source = root / relative
        destination = backup_root / relative
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, destination)

    print("✅ Backup created:", backup_root)

    for relative, encoded in FILES.items():
        destination = root / relative
        destination.write_bytes(decode(encoded))
        print("✅ Updated:", relative)

    for relative in FILES:
        actual = sha256(root / relative)
        expected = EXPECTED_PATCHED_SHA256[relative]
        if actual != expected:
            print("❌ Verification failed for", relative)
            return 3

    # Syntax-only TypeScript check. This intentionally ignores the project's
    # unrelated legacy TypeScript errors.
    node_check = r"""
const fs = require('fs');
const ts = require('typescript');
const files = process.argv.slice(1);
let failed = false;
for (const file of files) {
  const source = fs.readFileSync(file, 'utf8');
  const result = ts.transpileModule(source, {
    compilerOptions: {
      jsx: ts.JsxEmit.ReactJSX,
      target: ts.ScriptTarget.ES2022,
      module: ts.ModuleKind.ESNext,
    },
    reportDiagnostics: true,
    fileName: file,
  });
  const errors = (result.diagnostics || []).filter(
    (diagnostic) => diagnostic.category === ts.DiagnosticCategory.Error
  );
  if (errors.length) {
    failed = true;
    console.error(`Syntax errors in ${file}:`);
    for (const error of errors) {
      console.error(ts.flattenDiagnosticMessageText(error.messageText, '\n'));
    }
  }
}
process.exit(failed ? 1 : 0);
"""

    try:
        subprocess.run(
            [
                "node",
                "-e",
                node_check,
                str(root / "app/(tabs)/shop.tsx"),
                str(root / "app/context/PurchasesContext.tsx"),
            ],
            cwd=root,
            check=True,
        )
        print("✅ TypeScript syntax check passed.")
    except Exception as error:
        print("⚠️ Files were installed, but the optional syntax check could not run:")
        print("  ", error)

    print("\n✅ IAP repair installed successfully.")
    print("\nNext run:")
    print("  npx expo start -c")
    print("\nThen open Shop and tap ‘Restore Apple Purchases’ once.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
